"""Check proposed C natural layout with ctypes, without building a candidate."""
from pathlib import Path
import ctypes as C,hashlib,json
HERE=Path(__file__).resolve().parent
U32,I32,U64=C.c_uint32,C.c_int32,C.c_uint64
fields=[('hook',U32),('reason',U32),('classification',I32),('detail',U32),('valid',U64),('stage',U64),('app_index',U32),('app_count',U32),('page_index',U32),('form_id',U32),('page_hii',U64),('page_owner',I32),('owner_reason',U32),('owner_status',U64),('canonical_count',U32),('target_seen',U32),('frame_index',U32),('frame_kind',U32),('frame_count',U32),('frame_vtable_rva',U32),('control_index',U32),('control_vtable_rva',U32),('control_type',U32),('chrome_result',I32),('control_hii',U64),('control_owner',I32),('hii_class',U32),('opcode',U32),('opcode_length',U32),('varstore_id',U32),('question_id',U32),('varstore_offset',U32),('descriptor_flags',U32),('callback_bits',U32),('callback_module',U32),('callback_rva',U64),('method_slot',U32),('descriptor_byte',U32),('source_hii_class',U32),('ifr_pointer_class',U32),('frame_vtable_class',U32),('code_range_index',U32),('native_strings_hii',U64),('request_return_rva',U64),('request_return_module',U32),('provider_flags',U32),('depth',U32),('redirect_result',I32),('event_arg',U32),('event_action',U32),('crc32',U32),('reserved32',U32),('request_serial',U64),('reserved64',U64)]
class Record(C.Structure):_fields_=fields
class Region(C.Structure):_fields_=[('magic',U64),('revision',U32),('bytes',U32),('first_commit',U64),('request_commit',U64),('request_count',U64),('prompt_count',U64),('ack_count',U64),('writer_lock',U32),('flags',U32),('first',Record),('request',Record)]
assert C.sizeof(Record)==256 and C.sizeof(Region)==576
assert Record.control_hii.offset==112 and Record.crc32.offset==232 and Record.request_serial.offset==240
assert Region.first.offset==64 and Region.request.offset==320
assert 32<=0x40 and 0x40+C.sizeof(Region)==0x280<=4096
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
r={
 'status':'PROPOSED_SCHEMA_LAYOUT_CHECKED_NOT_COMPILED_IMPLEMENTATION',
 'header_sha256':sha(HERE/'diagnostic09.h'),'offset_in_owned_state':64,'region_bytes':576,'end_exclusive_in_owned_state':640,
 'unchanged_prefix_bytes':32,'gap_before_region':32,'records':{'first_state_offset':128,'request_state_offset':384,'record_bytes':256},
 'record_fields':[{'name':n,'offset':getattr(Record,n).offset,'bytes':C.sizeof(t)}for n,t in fields],
 'region_fields':[{'name':n,'offset':getattr(Region,n).offset,'bytes':C.sizeof(t)}for n,t in Region._fields_],
 'owned_range_proof':['Original platform AllocatePages-owned state is4096B, already checked exclusive against all LoadedImages, stack/tables, guard allocations and transaction/context; no adjacent page is touched.','New controller initializes only state+[0x40,0x280) before publishing any hook. Guard/provider readers require same immutable binding state_base/state_size4096 and valid unchanged public prefix.','Diagnostic header magic/revision/size and writable/readable region are checked separately. Diagnostic validity never participates in access grant, session owner, protected-page policy or rollback proof.','Guard logging uses no service call. First/current record publication uses a nonblocking inline atomic claim; contention marks incomplete/dropped and never spins or overwrites a pending record.','State remains allocated until poweroff under the existing resident lifetime. No separate allocation, pointer publication or unload path is introduced.'],
 'first_and_request_semantics':['Per-classification caller-owned stack scratch; first failed field within that original pass is retained. Successful tests or later redirect scans cannot replace it.','Only actual gated-entry denial publishes first record, once; redirect candidate probes receive no diagnostic sink. If nested reentry has already published the first record it remains unchanged and current request independently carries its own local failure.','Before p->request, commit current request record with a monotonically increasing request serial and PENDING flag; provider UI reads this exact pending record. Guard completion clears only matching pending serial.','Direct independent HII FFE2/action0 explicitly publishes hook9 with classification unavailable. It cannot inherit a stale guard/page record.','A pending request cannot be replaced by reentry; contention/overflow is marked incomplete. Prompt and ack counters are updated only by the existing UNCONFIGURED display/ack branch. No key code or text is recorded.','Counters saturate; readers validate version/size, stable even commit and CRC. Diagnostic failure returns unavailable while original policy return remains unchanged.'],
 'minimal_transport':['Only the existing provider UNCONFIGURED screen gains six <=72-column ASCII diagnostic lines. No new keyboard binding, mode switch, QR path or emergency return.','First/Request hook+reason, page/Form/owner, frame/control/type/vtable, request/prompt/ack sequence and CRC are enough for the next KVM capture. Missing fields explicitly show unavailable.','Optional post-return app Q export is deferred. No record rendering or firmware call after EBS or terminal high-TPL hold.'],
 'implementation_locations_proposed':['New isolated diagnostic_guard09 based on frozen07, with classification trace sink and owned recorder.','New isolated provider15_diagnostic09 based on P14; bounded state snapshot accessor, direct HII Verify origin, UNCONFIGURED display/ack counters only.','New isolated ram_transaction09 based on TX08; new exact assets/template/provider binding, owned-state diagnostic header initialization and distinct tool label. No new action/menu mode or Q exporter.'],
 'required_tests_before_integration':['Pure layout/CRC/overflow/torn/concurrent-writer fixtures using actual compiled recorder; assert writes only inside0x40..0x280.','Actual original kind4 constructor→traced classification, wrong-form index, page-owner failure, strict-chrome negative and real protected Setup form; precise distinct reason codes, no authority change.','Original07 versus new guard differential198-policy and106-chrome results plus independent13kind4 cases, including identical original-service call ordering; trace stores explicitly excluded from equivalence.','Redirect recursion preserves first/current request; direct FFE2 after prior denial has direct origin and no stale fields; failed diagnostic bounds never alter allow/deny.','Actual P15 UNCONFIGURED two prompts with standardESC/modelESC: distinct sequence+ack, no password collection/setter. Every new print EBS boundary and invalid/TPL/retired state preserve terminal behavior.','Exact P15 owner/template/caller rebinding, complete TX09 transaction/partial-start/rollback and real OVMF loaded-image validator; no prior hash pass transfer.'],
 'not_yet_done':['No new guard/provider/app has been compiled or integrated.','No diagnostic record has been captured on ASUS hardware.','No kind4 allowance or forced native-exit patch exists.']
}
(HERE/'schema_contract.json').write_text(json.dumps(r,indent=2)+'\n')
print(json.dumps({'header_sha256':r['header_sha256'],'contract_sha256':sha(HERE/'schema_contract.json'),'record_bytes':256,'region_bytes':576,'owned_end':640}))
